package paradox.music.nativeui;
import android.content.*;import android.os.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Bounded local startup timing and main-thread stack samples, written off the UI thread. */
public final class NativeMusicStartupTrace {
 private static final ScheduledExecutorService IO=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"Ultra-Music-Startup-Timing");t.setDaemon(true);return t;});
 private static File timeline,stalls,lastSample;private static long threadSampleAt;private static String threadSnapshot="";private static volatile long start,beat;private static volatile boolean active;private static ScheduledFuture<?> watch;private static final Handler MAIN=new Handler(Looper.getMainLooper());
 private static final Runnable HEARTBEAT=new Runnable(){public void run(){beat=SystemClock.elapsedRealtime();if(active)MAIN.postDelayed(this,500);}};
 public static synchronized void install(Context c){if(timeline==null){timeline=new File(c.getFilesDir(),"ultra-music-timing.txt");stalls=new File(c.getFilesDir(),"ultra-music-main-stalls.txt");lastSample=new File(c.getFilesDir(),"ultra-music-last-sample.txt");}}
 public static synchronized void begin(){start=SystemClock.elapsedRealtime();beat=start;threadSampleAt=0;threadSnapshot="";active=true;IO.execute(()->{try{write(timeline,"Startup elapsed timings\n",false);write(stalls,"Main-thread stall snapshots\n",false);write(lastSample,"No sample yet\n",false);}catch(Exception ignored){}});if(watch!=null)watch.cancel(false);MAIN.post(HEARTBEAT);watch=IO.scheduleAtFixedRate(()->sample(),500,500,TimeUnit.MILLISECONDS);event("startup begin");}
 public static void event(String name){if(!active)return;final String text="+"+(SystemClock.elapsedRealtime()-start)+"ms ["+Thread.currentThread().getName()+"] "+name+"\n";IO.execute(()->{try{write(timeline,text,true);}catch(Exception ignored){}});}
 private static void sample(){if(!active)return;long now=SystemClock.elapsedRealtime(),lag=now-beat;NativeMusicDiagnostics.heartbeat();if(now-start>120000){end();return;}try{StringBuilder s=new StringBuilder("LAST SAMPLE +").append(now-start).append("ms heartbeat lag=").append(lag).append("ms\n").append(NativeMusicDiagnostics.attemptSummary());Thread main=Looper.getMainLooper().getThread();s.append("MAIN ").append(main.getState()).append('\n');for(StackTraceElement x:main.getStackTrace())s.append("  at ").append(x).append('\n');if(lag>=750&&(threadSampleAt==0||now-threadSampleAt>=2000)){threadSnapshot=waitingThreads(now-start);threadSampleAt=now;}s.append(threadSnapshot);write(lastSample,s.toString(),false);if(lag>=750&&stalls.length()<4*1024*1024)write(stalls,s.toString(),true);}catch(Throwable ignored){}}
 static String waitingThreads(long elapsed){
  Map<Thread,StackTraceElement[]> all=Thread.getAllStackTraces();List<Thread> selected=new ArrayList<>();
  for(Map.Entry<Thread,StackTraceElement[]> e:all.entrySet())if(includeThread(e.getKey(),e.getValue()))selected.add(e.getKey());
  Collections.sort(selected,(a,b)->{int d=Integer.compare(priority(a,all.get(a)),priority(b,all.get(b)));return d!=0?d:a.getName().compareTo(b.getName());});
  StringBuilder out=new StringBuilder("\nCONTENDING THREAD SNAPSHOT +").append(elapsed).append("ms. Stack samples do not identify monitor owners.\n");
  for(Thread t:selected){out.append("Thread ").append(t.getName()).append(" id=").append(t.getId()).append(' ').append(t.getState()).append('\n');int n=0;for(StackTraceElement x:all.get(t)){if(n++>=64){out.append("  [stack capped]\n");break;}out.append("  at ").append(x).append('\n');}if(out.length()>80*1024){out.append("[thread snapshot capped]\n");break;}}
  return out.toString();
 }
 private static boolean relevant(StackTraceElement[] stack){for(StackTraceElement x:stack){String c=x.getClassName();if(c.contains("PluginServiceManager")||c.contains("ComponentManager")||c.contains("NativeMusicMainThread")||c.equals("sqk")||c.equals("sqi")||c.equals("sqj")||c.equals("android.os.BinderProxy"))return true;}return false;}
 private static int priority(Thread t,StackTraceElement[] stack){return t.getName().contains("GoogleApiHandler")?0:relevant(stack)?1:t.getState()==Thread.State.BLOCKED?2:3;}
 private static boolean includeThread(Thread t,StackTraceElement[] stack){if(t==Thread.currentThread()||t==Looper.getMainLooper().getThread())return false;if(t.getName().contains("GoogleApiHandler")||relevant(stack))return true;if(t.getState()==Thread.State.BLOCKED)return true;if(t.getState()!=Thread.State.WAITING&&t.getState()!=Thread.State.TIMED_WAITING)return false;boolean wait=false;for(StackTraceElement x:stack){String c=x.getClassName();if(c.contains("BlockingQueue")||c.contains("LinkedTransferQueue")||c.equals("java.lang.ref.ReferenceQueue"))return false;if(c.contains("CountDownLatch")||c.contains("FutureTask")||c.contains("LockSupport")||(c.equals("java.lang.Object")&&x.getMethodName().equals("wait")))wait=true;}return wait;}
 public static synchronized void end(){event("startup ended");active=false;if(watch!=null){watch.cancel(false);watch=null;}MAIN.removeCallbacks(HEARTBEAT);}
 public static String readSaved(){return read(lastSample,96*1024)+"\n"+read(timeline,5*1024*1024)+"\n"+read(stalls,5*1024*1024);}
 public static String readSummary(){return read(lastSample,96*1024)+"\n"+read(timeline,32*1024);}
 private static String read(File f,int cap){try{if(f==null||!f.exists())return "";ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(f)){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1&&out.size()<cap)out.write(b,0,n);}return out.toString("UTF-8");}catch(Exception e){return "";}}
 private static void write(File f,String s,boolean append)throws Exception{if(f==null)return;try(FileOutputStream out=new FileOutputStream(f,append)){out.write(s.getBytes("UTF-8"));out.getFD().sync();}}
}
